package com.vandorlabs.neoforge.propulsion;
import com.google.gson.*;import com.vandorlabs.propulsion.PropulsionObjMesh;import java.nio.file.*;import java.util.*;
/** Canonical OBJ kernel compared with actual released loader bytes in every authored pose. */
public final class PropulsionObjChecks {
 public static void main(String[] args)throws Exception{int poses=0,quads=0;try(var lines=Files.lines(Path.of(args[0]))){for(String line:(Iterable<String>)lines::iterator){var r=JsonParser.parseString(line).getAsJsonObject();if(!r.get("source").getAsString().endsWith(".obj"))continue;var model=NativePropulsionAssets.model(r.get("id").getAsString());int x=r.get("x").getAsInt(),y=r.get("y").getAsInt();var expected=r.getAsJsonArray("quads");boolean[] used=new boolean[expected.size()];for(var face:model.geometry()){JsonObject template=null;for(var e:expected){var q=e.getAsJsonObject();if(face.sprite.equals(q.get("sprite").getAsString())){template=q;break;}}if(template==null)throw new AssertionError("Source sprite");var extent=template.getAsJsonArray("extent");var sprite=new PropulsionObjMesh.Sprite(){public float minU(){return extent.get(0).getAsFloat();}public float maxU(){return extent.get(1).getAsFloat();}public float minV(){return extent.get(2).getAsFloat();}public float maxV(){return extent.get(3).getAsFloat();}public int width(){return 128;}public int height(){return 128;}};int[] data=new int[32];for(int v=0;v<4;v++)data[v*8+3]=-1;int direction=PropulsionObjMesh.bake(face,x,y,sprite,data),best=-1;long error=Long.MAX_VALUE;for(int i=0;i<expected.size();i++){if(used[i])continue;var q=expected.get(i).getAsJsonObject();if(!face.sprite.equals(q.get("sprite").getAsString())||direction!=q.get("face").getAsInt())continue;var target=q.getAsJsonArray("data");long difference=0;for(int a=0;a<data.length;a++)if(data[a]!=target.get(a).getAsInt())difference++;if(difference<error){error=difference;best=i;}}if(error!=0)throw new AssertionError("Actual Source OBJ "+r.get("id")+"/"+x+"/"+y+" sprite="+face.sprite+" differingFields="+error+" direction="+direction+" actual="+java.util.Arrays.toString(data)+" expected="+(best<0?"none":expected.get(best)));used[best]=true;quads++;}if(model.geometry().size()!=expected.size())throw new AssertionError("Source OBJ quad coverage");poses++;}}if(poses!=1316||quads!=35912)throw new AssertionError("Source OBJ coverage");System.out.println("Native propulsion OBJ PASS poses="+poses+" quads="+quads+" exactSource positions/UVcontraction/roundnormals/faceorientation");}
}
